fn peek(path: Text) -> Text uses fs or fail {
    return try read_file(path)
}

fn main() uses io, fs {
    check peek("{DATA}/a.txt") {
        ok body {
            print("READ IT")
        }
        fail why {
            print("SWALLOWED THE REFUSAL")
        }
    }
    print("CARRIED ON")
}
